import {roomWalls,roomHeightAt,roomVolumes} from './room-shapes.mjs';
import {deformedHull} from './hull-terrain.mjs';
import {terrainColor,waterPolygon} from './map-view.mjs';
import {triangles,PLAYER_HEIGHT,SHIP_SCALE} from './gsv.mjs';
let avatar=[];
export async function loadAvatar(){const [response,img]=await Promise.all([fetch('./assets/player.bin'),new Promise((resolve,reject)=>{const i=new Image();i.onload=()=>resolve(i);i.onerror=reject;i.src='./assets/player.png';})]);if(!response.ok)throw Error('Player mesh could not load');const a=new Float32Array(await response.arrayBuffer()),c=document.createElement('canvas');c.width=img.width;c.height=img.height;const ctx=c.getContext('2d');ctx.drawImage(img,0,0);const pixels=ctx.getImageData(0,0,c.width,c.height).data;for(let i=0;i<a.length;i+=27){const vertices=[0,9,18].map(k=>Array.from(a.slice(i+k,i+k+3))),u=(a[i+6]+a[i+15]+a[i+24])/3,v=(a[i+7]+a[i+16]+a[i+25])/3,x=Math.min(c.width-1,Math.max(0,Math.floor(u*c.width))),y=Math.min(c.height-1,Math.max(0,Math.floor(v*c.height))),n=(y*c.width+x)*4;avatar.push({vertices,color:`rgb(${pixels[n]},${pixels[n+1]},${pixels[n+2]})`});}return avatar.length;}
function polygon(ctx,points,fill,stroke){if(points.some(p=>!p))return;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(p.x,p.y):ctx.moveTo(p.x,p.y));ctx.closePath();if(fill){ctx.fillStyle=fill;ctx.fill();}if(stroke){ctx.strokeStyle=stroke;ctx.lineWidth=.65;ctx.stroke();}}
export function drawAvatar(ctx,proj,x,y,z){const faces=avatar.map(t=>({pts:t.vertices.map(v=>proj(x+v[0],y+v[1],z+v[2])),color:t.color})).filter(t=>t.pts.every(Boolean));faces.sort((a,b)=>b.pts.reduce((s,p)=>s+(p.depth||0),0)-a.pts.reduce((s,p)=>s+(p.depth||0),0));for(const t of faces)polygon(ctx,t.pts,t.color);}
export function scaleView(ctx,w,h,layout,room,mode,yaw,pitch,zoom){const ship=mode==='ship',sy=Math.sin(yaw),cy=Math.cos(yaw),sp=Math.sin(pitch),cp=Math.cos(pitch),faces=[];
 const target=ship?[0,0,0]:[room.x+room.w/2,room.y+1,room.z+room.d/2];const scale=Math.min(w/29000,h/16000)*zoom*13500/SHIP_SCALE,distance=8/zoom,focal=Math.min(w,h)*.85;
 function proj(x,y,z){const dx=x-target[0],dy=y-target[1],dz=z-target[2],a=dx*cy-dz*sy,b=dx*sy+dz*cy,vertical=dy*cp-b*sp,depth=b*cp+dy*sp;
 if(ship)return {x:w/2+a*scale,y:h/2-vertical*scale,depth:-depth};const d=distance-depth;if(d<.15)return null;return {x:w/2+a*focal/d,y:h/2-vertical*focal/d,depth:d};}
 function add(vertices,fill,stroke){if(!ship){const depth=v=>distance-((v[0]-target[0])*sy+(v[2]-target[2])*cy)*cp-(v[1]-target[1])*sp;const clipped=[];for(let i=0;i<vertices.length;i++){const a=vertices[i],b=vertices[(i+1)%vertices.length],da=depth(a),db=depth(b),insideA=da>=.16,insideB=db>=.16;if(insideA)clipped.push(a);if(insideA!==insideB){const t=(.16-da)/(db-da);clipped.push(a.map((x,k)=>x+(b[k]-x)*t));}}vertices=clipped;if(vertices.length<3)return;}const pts=vertices.map(v=>proj(...v));if(pts.every(Boolean))faces.push({pts,fill,stroke,depth:pts.reduce((s,p)=>s+p.depth,0)/pts.length});}
 if(ship){for(const t of deformedHull(layout)){if(t.terrain){add(t.v,terrainColor(t.local),null);const water=waterPolygon(t.local);if(water.length>2)add(water.map(p=>p.map((v,k)=>v+layout.ship.origin[k])),'#498c9f',null);continue;}const garden=t.n[1]>.99&&t.v[0][1]<SHIP_SCALE*.15,shade=.55+.45*Math.abs(t.n[1]);add(t.v,garden?'#49776a':`rgb(${Math.round(45*shade)},${Math.round(77*shade)},${Math.round(93*shade)})`,'#91c7c526');}for(const r of layout.rooms.filter(r=>r.edgeSection))add(r.aperture.vertices.map(p=>p.map((v,k)=>v+layout.ship.origin[k])),r.type==='hangar'?'#09080f':'#b5e4dc','#eee1bc');}
 else {const {x,z,w:rw,d,y,h:rh}=room,outline=room.polygon||[[x,z],[x+rw,z],[x+rw,z+d],[x,z+d]];
 if(room.floorMesh)for(const v of room.floorMesh)add(v,'#667468',null);else for(const v of roomVolumes(room))add(v.polygon.map(([px,pz])=>[px,v.y,pz]),'#667468','#b5c7ac');
 if(room.edgeSection&&!room.plateSection){const v=room.vertices;for(const ids of [[0,1,2,3],[1,5,6,2],[5,4,7,6],[4,0,3,7]]){const face=ids.map(i=>v[i]),mx=face.reduce((s,p)=>s+p[0],0)/4-target[0],mz=face.reduce((s,p)=>s+p[2],0)/4-target[2];if(mx*sy+mz*cy<=0){if(ids[0]===0&&ids[1]===1){const a=room.aperture.vertices;for(let i=0;i<4;i++)add([face[i],face[(i+1)%4],a[(i+1)%4],a[i]],'#989b8a','#c9c8ac');add(a,room.type==='hangar'?'#17212e':'#81adba','#eee1bc');}else add(face,'#989b8a','#c9c8ac');}}}
 else for(const face of roomWalls(room)){const mx=(face[0][0]+face[1][0])/2-target[0],mz=(face[0][2]+face[1][2])/2-target[2];if(mx*sy+mz*cy<=0)add(face,'#989b8a','#c9c8ac');}
 function box(x,y,z,w,h,d,color){const pts=[[x,y,z],[x+w,y,z],[x+w,y,z+d],[x,y,z+d],[x,y+h,z],[x+w,y+h,z],[x+w,y+h,z+d],[x,y+h,z+d]];for(const f of [[0,1,5,4],[1,2,6,5],[2,3,7,6],[3,0,4,7],[4,5,6,7]])add(f.map(i=>pts[i]),color,'#dddbc133');}
 if(room.frameThickness){const t=room.frameThickness,inset=Math.min(rw,d)*.3;for(const [px,pz] of [[x+inset,z+inset],[x+rw-inset,z+inset],[x+inset,z+d-inset],[x+rw-inset,z+d-inset]])box(px-t/2,y,pz-t/2,t,roomHeightAt(room,px,pz),t,'#d1cdb5');
 for(const pz of [z+inset,z+d-inset])box(x+inset,y+Math.min(roomHeightAt(room,x+inset,pz),roomHeightAt(room,x+rw-inset,pz))-t,pz-t/2,rw-inset*2,t,t,'#dfd6b8');
 for(const px of [x+inset,x+rw-inset])box(px-t/2,y+Math.min(roomHeightAt(room,px,z+inset),roomHeightAt(room,px,z+d-inset))-t,z+inset,t,t,d-inset*2,'#d4ceb4');
 const sky=layout.skylights?.find(s=>s.room===room.id);if(sky){const sw=sky.width,sd=sky.depth,cx=sky.x,cz=sky.z;add([[cx-sw/2,y+rh-.1,cz-sd/2],[cx+sw/2,y+rh-.1,cz-sd/2],[cx+sw/2,y+rh-.1,cz+sd/2],[cx-sw/2,y+rh-.1,cz+sd/2]],'#e9f3d5','#f9f3cb');
 // Daylight reaches the floor from the modest surface lantern.
 add([[cx-sw*.7,y+.02,cz-sd*.7],[cx+sw*.7,y+.02,cz-sd*.7],[cx+sw*.7,y+.02,cz+sd*.7],[cx-sw*.7,y+.02,cz+sd*.7]],'#aab998',null);}}
 }
 faces.sort((a,b)=>b.depth-a.depth);for(const f of faces)polygon(ctx,f.pts,f.fill,f.stroke);
 if(ship){const c=layout.config,o=layout.ship.origin;for(const y of [o[1]+Math.min(...layout.rooms.map(r=>r.y)),o[1]])polygon(ctx,[[-c.length/2,-c.width/2],[c.length/2,-c.width/2],[c.length/2,c.width/2],[-c.length/2,c.width/2]].map(([x,z])=>proj(x+o[0],y,z+o[2])),null,'#ffe5a4');const p=proj(...o);ctx.fillStyle='#ffe5a4';ctx.font='14px sans-serif';ctx.textAlign='left';ctx.fillText('Interior section · garden '+(layout.ship.garden+1),p.x+10,p.y);ctx.fillStyle='#abc1c7';ctx.fillText('Player below pixel size. Use Third person.',18,h-65,w-36);}
 else {for(let x=Math.ceil(Math.max(room.x,target[0]-100));x<=Math.min(room.x+room.w,target[0]+100);x++){const a=proj(x,room.y+.01,room.z),b=proj(x,room.y+.01,room.z+room.d);if(a&&b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle='#b8e3d21a';ctx.stroke();}}for(let z=Math.ceil(Math.max(room.z,target[2]-100));z<=Math.min(room.z+room.d,target[2]+100);z++){const a=proj(room.x,room.y+.01,z),b=proj(room.x+room.w,room.y+.01,z);if(a&&b){ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.strokeStyle='#b8e3d21a';ctx.stroke();}}drawAvatar(ctx,proj,target[0],room.y,target[2]);const a=proj(target[0]+.65,room.y,target[2]),b=proj(target[0]+.65,room.y+PLAYER_HEIGHT,target[2]);if(a&&b){ctx.strokeStyle='#ffe4a4';ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.fillStyle='#ffe4a4';ctx.font='14px sans-serif';ctx.textAlign='left';ctx.fillText('1.95 m',b.x+8,b.y);}ctx.fillStyle='#b6cdd0';ctx.font='14px sans-serif';ctx.textAlign='left';ctx.fillStyle='#152528dd';ctx.fillRect(12,h-105,w-24,65);ctx.fillStyle='#eff2d7';ctx.fillText(`${room.w.toFixed(1)} × ${room.d.toFixed(1)} m · ${room.h.toFixed(1)} m clear height`,22,h-80,w-44);ctx.fillText(`1 m grid${room.daylight?' · '+room.daylight:''}`,22,h-56,w-44);}
}
